import requests
from bs4 import BeautifulSoup
import random
import string
import time

def generate_password(len=8):
    characters = string.ascii_lowercase + string.ascii_uppercase + string.digits
    return ''.join(random.choice(characters) for i in range(len))

def sign_up(username, password):
    data = {
        'username': username,
        'password': password
    }
    response = requests.post('https://www.tiktok.com/sign-up', data=data)
    if response.status_code == 200:
        print(f"Sign-up successful for user: {username}")
        return True
    else:
        print(f"Sign-up failed for user: {username}")
        return False

def scrape_videos():
    url = 'https://www.tiktok.com/explore'
    response = requests.get(url)
    if response.status_code == 200:
        soup = BeautifulSoup(response.text, 'html.parser')
        video_links = [a['href'] for a in soup.find_all('a', href=True) if '/video/' in a['href']]
        return video_links
    else:
        print("Failed to fetch TikTok explore page")
        return []

def main():
    usernames = [f"user{i}" for i in range(10)]
    passwords = [generate_password() for _ in range(10)]

    for username, password in zip(usernames, passwords):
        if sign_up(username, password):
            video_links = scrape_videos()
            if video_links:
                print(f"Scraped Videos for user {username}:")
                for link in video_links:
                    print(link)
            else:
                print(f"No videos found for user {username}")
        time.sleep(2)  # To avoid rate limiting

if __name__ == "__main__":
    main()
